import express from "express";

type Product = { id: string; name: string; price: number };
const products: Product[] = [
    { id: "notebook", name: "Notebook", price: 4.5 },
    { id: "pen", name: "Pen", price: 1.25 },
];

export const app = express();

// TODO: register GET /products/:id and return the matching product
app.get("/products", function list(request, response) {
    response.json(products);
});
